-- Eşrefli Köyü (Akpınar) içme suyu şebekesi — Hat 1 + Hat 2 aktarımı (2026-10-15)
-- Kaynak: Netcad çizimi MM.kml (geometri) + E_REFL__HAT1-HAT2.pdf hesap tabloları (çap, uzunluk, kot, işletme basıncı).
-- Önce SQL-baca-vana-turleri-2026-10-15.sql (BÖLÜM 1 ve 2) çalıştırılmış olmalı.
-- Yalnız YENİ kayıt ekler: 18 baca, 4 vana, 18 hat parçası (Eşrefli deposu KS-DEP-0013'e bağlı).
-- Baca/vana konumu çizimdeki yazı (etiket) noktasından alındığı için "konum yaklaşık" işaretlidir; sahada doğrulanacak.
begin;
do $$
declare v_depo bigint;
begin
  select id into v_depo from tesis where kod = 'KS-DEP-0013' and silindi is null;
  if v_depo is null then raise exception 'Eşrefli deposu (KS-DEP-0013) bulunamadı'; end if;
  if exists (select 1 from hat where tesis_id = v_depo) then raise exception 'Eşrefli deposunun hatları zaten var — aktarım yapılmadı'; end if;
  if exists (select 1 from tesis where kod like 'KS-BAC-%' or kod like 'KS-VAN-%') then raise exception 'Baca/vana kayıtları zaten var — aktarım yapılmadı'; end if;

end $$;
commit;
